 private static NBTTagCompound input(boolean chip,int profile){NBTTagCompound tag=new NBTTagCompound();if(profile<=1)return tag;tag.setBoolean("ChipSlot",chip);tag.setBoolean("AnyToken",profile%2==0);tag.setInteger("AllowedTokens",profile==3?4:8);tag.setInteger("TokenBehavior",profile==3?1:profile==5?2:profile==6?3:0);tag.setLong("TokenPulseUntil",110);tag.setBoolean("TokenToggled",profile==5);tag.setBoolean("TokenToggleApplied",profile==6);tag.setLong("TokenInsertStarted",95);tag.setLong("TokenInsertionSequence",11);tag.setInteger("TokenLogo",2);tag.setLong("TokenRejectedUntil",112);if(profile==5||profile==6)tag.setUniqueId("TokenReturnTo",new UUID(17,29));ItemStack token=new ItemStack(profile==7?(chip?ModItems.ACCESS_CARD:ModItems.DATA_CHIP):(chip?ModItems.DATA_CHIP:ModItems.ACCESS_CARD),1,2);NBTTagCompound payload=new NBTTagCompound();payload.setString("ReaderCopyOwnership","private:one");token.setTagCompound(payload);tag.setTag("InsertedToken",token.writeToNBT(new NBTTagCompound()));tag.setInteger("ControlMountVersion",2);tag.setInteger("BaseHeight",profile%4);tag.setInteger("BaseTilt",profile/2%4);tag.setInteger("TiltDirection",profile/3%4);tag.setInteger("MountRotation",profile%4);tag.setInteger("Channel",13);tag.setIntArray("RedstoneChannels",new int[]{13,17});if(profile>=6){NBTTagCompound forge=new NBTTagCompound(),all=new NBTTagCompound(),main=new NBTTagCompound();main.setIntArray("Channels",new int[]{29,31});main.setInteger("Range",64);main.setBoolean("Local",false);all.setTag("main",main);forge.setTag(com.vandorlabs.redstone.TransmissionSettings.SETTINGS,all);tag.setTag("ForgeData",forge);}return tag;}
 private static NBTTagCompound owned(NBTTagCompound tag){NBTTagCompound out=new NBTTagCompound();for(String key:PRIVATE)if(tag.hasKey(key))out.setTag(key,tag.getTag(key).copy());return out;}
 private static TileEntityTokenSlot install(NonRenderingChecks.MemoryWorld world,BlockTokenSlot block,int meta,BlockPos pos,NBTTagCompound initial,boolean fresh){world.setBlockState(pos,block.getStateFromMeta(meta),2);TileEntityTokenSlot tile=(TileEntityTokenSlot)world.getTileEntity(pos);if(!fresh){NBTTagCompound tag=initial.copy();tag.setInteger("x",pos.getX());tag.setInteger("y",pos.getY());tag.setInteger("z",pos.getZ());tile.readFromNBT(tag);}tile.refresh();return tile;}
 private static JsonObject apply(NonRenderingChecks.MemoryWorld world,BlockTokenSlot block,int meta,NBTTagCompound initial,NBTTagCompound values){TileEntityTokenSlot owner=install(world,block,meta,TARGET,initial,false);NBTTagCompound savedBefore=owner.writeToNBT(new NBTTagCompound()),privateBefore=owned(savedBefore);String clipboard=values.toString();JsonObject row=new JsonObject();row.addProperty("chip",block.chip);row.addProperty("meta",meta);row.addProperty("target",initial.toString());row.addProperty("values",clipboard);row.addProperty("before",ProgrammableSettings.capture(world,TARGET).toString());row.addProperty("ownedBefore",privateBefore.toString());row.addProperty("outputBefore",owner.getOutputLevel());row.addProperty("applied",ProgrammableSettings.apply(world,TARGET,values));row.addProperty("after",ProgrammableSettings.capture(world,TARGET).toString());NBTTagCompound saved=owner.writeToNBT(new NBTTagCompound());row.addProperty("ownedAfter",owned(saved).toString());row.addProperty("saved",saved.toString());row.addProperty("outputAfter",owner.getOutputLevel());if(!clipboard.equals(values.toString())||world.getTileEntity(TARGET)!=owner||!privateBefore.equals(owned(saved)))throw new AssertionError("Clipboard, physical reader or private credential/return ownership changed");return row;}
 private static void clear(NonRenderingChecks.MemoryWorld world,com.vandorlabs.tiles.DeferredTileLoad deferred){for(net.minecraft.tileentity.TileEntity tile:new ArrayList<>(world.tiles.values()))tile.invalidate();net.minecraftforge.event.world.WorldEvent.Unload event=new net.minecraftforge.event.world.WorldEvent.Unload(world);com.vandorlabs.redstone.RedstoneChannels.worldUnloaded(event);deferred.worldUnload(event);com.vandorlabs.tiles.WorldActionAuthorization.unload(event);world.clear();}
 public static void main(String[] args)throws Exception{PropulsionPlacementLegacyOracle.initialize();net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileEntityTokenSlot.class,new net.minecraft.util.ResourceLocation("vandorlabs","token_slot"));net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(ModItems.ACCESS_CARD);net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(ModItems.DATA_CHIP);List<BlockTokenSlot> blocks=new ArrayList<>();for(net.minecraft.block.Block block:ModBlocks.BLOCKS)if(block instanceof BlockTokenSlot){blocks.add((BlockTokenSlot)block);net.minecraftforge.fml.common.registry.ForgeRegistries.BLOCKS.register(block);}if(blocks.size()!=2)throw new AssertionError("Reader roles");NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);world.time=100;java.lang.reflect.Constructor<com.vandorlabs.tiles.DeferredTileLoad> constructor=com.vandorlabs.tiles.DeferredTileLoad.class.getDeclaredConstructor();constructor.setAccessible(true);com.vandorlabs.tiles.DeferredTileLoad deferred=constructor.newInstance();File output=new File(args[0]);output.getParentFile().mkdirs();Gson gson=new Gson();int captures=0,partials=0;try(PrintWriter out=new PrintWriter(output,"UTF-8")){for(BlockTokenSlot block:blocks)for(int meta=0;meta<16;meta++)for(int profile=0;profile<8;profile++){NBTTagCompound initial=input(block.chip,profile);install(world,block,meta,SOURCE,initial,profile==0);NBTTagCompound capture=ProgrammableSettings.capture(world,SOURCE);for(String key:PRIVATE)if(capture.hasKey(key)||capture.getCompoundTag("signal_settings").hasKey(key))throw new AssertionError("Private credential data entered clipboard");JsonObject row=apply(world,block,meta^3,input(block.chip,6),capture);row.addProperty("kind","capture");row.addProperty("input",initial.toString());row.addProperty("fresh",profile==0);row.addProperty("sourceMeta",meta);out.println(gson.toJson(row));clear(world,deferred);captures++;}for(BlockTokenSlot block:blocks)for(int meta:new int[]{0,2,5,8,13,15})for(int profile:new int[]{0,2,3,4,5,6,7})for(int edit=0;edit<EDITS.length;edit++){JsonObject row=apply(world,block,meta,input(block.chip,profile),JsonToNBT.getTagFromJson(EDITS[edit]));row.addProperty("kind","partial");row.addProperty("edit",edit);out.println(gson.toJson(row));clear(world,deferred);partials++;}}if(captures!=256||partials!=2772)throw new AssertionError("Reader matrix bounds captures="+captures+" partials="+partials);byte[] raw=java.nio.file.Files.readAllBytes(output.toPath());StringBuilder hash=new StringBuilder();for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(raw))hash.append(String.format(java.util.Locale.ROOT,"%02x",b&255));if(raw.length!=7071698||!hash.toString().equals("fb55a743e731e84c9f714eb0e35a867fcf838f70535258d6b8489a4a3b575bcc"))throw new AssertionError("Released reader clipboard callbacks changed: "+hash);System.out.println("Actual Copifier reader Source PASS captures="+captures+" partials="+partials+" bothReaders/allMetadata/outputOnlyChannels/activeCannotMintSignal/privateCredential+returnStateUnchanged");}
